class Solution {
    public boolean isPalindrome(String s) {
        int i = 0;
        int j = s.length() - 1;
        while (i < j) {
            char a = s.charAt(i);
            char b = s.charAt(j);
            if (!Character.isLetter(a)) {
                i++;
            } else if (!Character.isLetter(b)) {
                j--;
            } else {
                if (a != b) {
                    return false;
                }
                i++;
                j--;
            }
        }
        return true;
    }
}
